import java.sql.*;public class Main{static void batch(Connection c,String[][]rows)throws SQLException{boolean old=c.getAutoCommit();c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("INSERT INTO bus_pass(pass_id,register_no,student_name,route_no,boarding_stop,valid_until,amount_paid) VALUES(?,?,?,?,?,?,?)")){int n=0;for(String[]r:rows){p.setString(1,r[0]);p.setString(2,r[1]);p.setString(3,r[2]);p.setInt(4,Integer.parseInt(r[3]));p.setString(5,r[4]);p.setDate(6,Date.valueOf(r[5]));p.setBigDecimal(7,new java.math.BigDecimal(r[6]));p.addBatch();if(++n%1000==0)p.executeBatch();}p.executeBatch();c.commit();}catch(Exception e){c.rollback();if(e instanceof SQLException)throw (SQLException)e;throw new SQLException(e);}finally{c.setAutoCommit(old);}}public static void main(String[]a){System.out.println("PassLoader batch size 1000; run with MySQL Connector/J and schema.sql.");}}